import csv
import io

def export_rows(rows):
    output = io.StringIO(newline="")
    writer = csv.writer(output, lineterminator="\n")
    writer.writerow(["title", "body"])
    for row in rows:
        writer.writerow([row["title"], row["body"]])
    return output.getvalue()

